 private static function normalized(string $s):string{return mb_strtolower(trim($s),'UTF-8');}
 private static function findColumn(array $schema,array $patterns):?string{foreach($patterns as $pattern)foreach($schema as $col){$name=self::normalized((string)$col['name']);if(preg_match($pattern,$name))return (string)$col['name'];}return null;}
