 private static function num(mixed $v):?float{if($v===null||$v==='')return null;if(is_int($v)||is_float($v))return (float)$v;$s=trim((string)$v);$s=str_replace(["\xc2\xa0",' '],'',$s);if(str_contains($s,',')&&str_contains($s,'.'))$s=strrpos($s,',')>strrpos($s,'.')?str_replace(['.',','],['','.'],$s):str_replace(',','',$s);elseif(str_contains($s,',')&&!str_contains($s,'.'))$s=str_replace(',','.',$s);return is_numeric($s)?(float)$s:null;}
