 private static function dateColumn(array $schema):?string{return self::findColumn($schema,['/(?:date|time|tanggal|waktu|period|month|year)/u']);}
 private static function metric(array $schema,string $q):?array{
  $q=self::normalized($q);$revenue=static fn()=>self::findColumn($schema,['/(?:revenue|sales|amount|omzet|pendapatan|penjualan|total[_ ]?price|line[_ ]?total|nilai[_ ]?transaksi)/u']);
  if(preg_match('/(?:profit|laba|menguntungkan)/u',$q)){$col=self::findColumn($schema,['/(?:gross[_ ]?profit|profit|laba|keuntungan)/u']);return $col?['type'=>'sum','column'=>$col,'label'=>'Total '.$col,'currency'=>self::currencyFor($col,$schema)]:null;}
  if(preg_match('/(?:growth|growing|pertumbuhan|bertumbuh|tumbuh)/u',$q)){$col=$revenue();if($col)return ['type'=>'sum','column'=>$col,'label'=>'Total '.$col,'currency'=>self::currencyFor($col,$schema)];$qty=self::findColumn($schema,['/(?:quantity|qty|jumlah|unit|terjual)/u']);$price=self::findColumn($schema,['/(?:unit[_ ]?price|price|harga|tarif)/u']);if($qty&&$price)return ['type'=>'derived_revenue','quantity'=>$qty,'price'=>$price,'label'=>'Nilai transaksi (quantity × unit price)','currency'=>self::currencyFor($price,$schema)];return null;}
