 private static function currencyFor(string $col,array $schema):?string{foreach($schema as $item)if(strcasecmp((string)($item['name']??''),$col)===0&&in_array(strtoupper((string)($item['currency']??'')),['IDR','USD','GBP','EUR'],true))return strtoupper((string)$item['currency']);if(preg_match('/(?:price|amount|revenue|sales|omzet|pendapatan|penjualan)/i',$col)){foreach($schema as $item)if(preg_match('/currency|mata uang/i',(string)($item['name']??'')))return null;if(stripos($col,'gbp')!==false||stripos($col,'sterling')!==false)return 'GBP';}return null;}
