 private static function dateFilter(array $rows,array $schema,string $q):array{$dateCol=self::dateColumn($schema);$q=self::normalized($q);if(!$dateCol)return [$rows,null,null];$start=null;$end=null;$today=new DateTimeImmutable('today');if(str_contains($q,'bulan ini')||str_contains($q,'this month')){$start=$today->modify('first day of this month');$end=$today->modify('last day of this month')->setTime(23,59,59);}elseif(str_contains($q,'bulan lalu')||str_contains($q,'last month')){$start=$today->modify('first day of last month');$end=$today->modify('last day of last month')->setTime(23,59,59);}elseif(str_contains($q,'tahun ini')||str_contains($q,'this year')){$start=$today->setDate((int)$today->format('Y'),1,1);$end=$start->setDate((int)$today->format('Y'),12,31)->setTime(23,59,59);}elseif(str_contains($q,'tahun lalu')||str_contains($q,'last year')){$year=(int)$today->format('Y')-1;$start=$today->setDate($year,1,1);$end=$today->setDate($year,12,31)->setTime(23,59,59);}else{$months=['januari'=>1,'jan'=>1,'februari'=>2,'feb'=>2,'maret'=>3,'mar'=>3,'april'=>4,'apr'=>4,'mei'=>5,'may'=>5,'juni'=>6,'jun'=>6,'juli'=>7,'jul'=>7,'agustus'=>8,'agu'=>8,'aug'=>8,'september'=>9,'sep'=>9,'oktober'=>10,'okt'=>10,'oct'=>10,'november'=>11,'nov'=>11,'desember'=>12,'des'=>12,'december'=>12,'dec'=>12];$years=[];preg_match_all('/\b(?:19|20)\d{2}\b/',$q,$ym);$years=array_map('intval',$ym[0]??[]);$chosenMonths=[];foreach($months as $word=>$num)if(preg_match('/\b'.preg_quote($word,'/').'\b/u',$q))$chosenMonths[]=$num;if(count($chosenMonths)===1){$year=$years[0]??null;$start=($year?new DateTimeImmutable($year.'-01-01'):new DateTimeImmutable('first day of this month'))->setDate($year?:((int)$today->format('Y')),$chosenMonths[0],1);$end=$start->modify('last day of this month')->setTime(23,59,59);}elseif(count($years)===1){$start=new DateTimeImmutable($years[0].'-01-01');$end=new DateTimeImmutable($years[0].'-12-31 23:59:59');}}
  preg_match_all('/\b(?:19|20)\d{2}-\d{2}-\d{2}\b/',$q,$dateMatches);if(count($dateMatches[0]??[])>=2){$from=(string)$dateMatches[0][0];$to=(string)$dateMatches[0][1];$fromDate=DateTimeImmutable::createFromFormat('!Y-m-d',$from);$toDate=DateTimeImmutable::createFromFormat('!Y-m-d',$to);if(!$fromDate||!$toDate||$fromDate->format('Y-m-d')!==$from||$toDate->format('Y-m-d')!==$to)return [[], $dateCol,['start'=>$from,'end'=>$to]];$start=$fromDate->setTime(0,0,0);$end=$toDate->setTime(23,59,59);if($start>$end)return [[], $dateCol,['start'=>$from,'end'=>$to]];}if(!$start||!$end)return [$rows,$dateCol,null];$filtered=[];foreach($rows as $row){$d=self::dateValue(self::value($row,$dateCol));if($d&&$d>=$start&&$d<=$end)$filtered[]=$row;}return [$filtered,$dateCol,['start'=>$start->format('Y-m-d'),'end'=>$end->format('Y-m-d')]];}
 private static function rowMetric(array $row,array $metric):?float{return match($metric['type']){'sum'=>self::num(self::value($row,$metric['column'])),'derived_revenue'=>(($q=self::num(self::value($row,$metric['quantity'])))!==null&&($p=self::num(self::value($row,$metric['price'])))!==null?$q*$p:null),'ratio'=>(($d=self::num(self::value($row,$metric['denominator'])))&&$d!=0?((self::num(self::value($row,$metric['numerator']))??0)/$d*100):null),'count'=>1.0,default=>null};}
 private static function insuff(string $reason,array $basis=[]):array{return ['status'=>'insufficient','answer'=>self::INSUFFICIENT,'metrics'=>[],'chart'=>['type'=>'bar','labels'=>[],'values'=>[]],'table'=>[],'insights'=>[],'recommendations'=>[],'basis'=>$basis,'reason'=>$reason];}
 private static function group(array $rows,array $metric,string $dimension):array{$groups=[];foreach($rows as $row){$key=trim((string)self::value($row,$dimension));if($key==='')$key='(kosong)';if(!isset($groups[$key]))$groups[$key]=['value'=>0.0,'rows'=>0,'distinct'=>[],'numerator'=>0.0,'denominator'=>0.0];if(($metric['type']??'')==='distinct'){$unique=trim((string)self::value($row,(string)$metric['column']));if($unique!=='')$groups[$key]['distinct'][$unique]=true;}elseif(($metric['type']??'')==='ratio'){$n=self::num(self::value($row,(string)$metric['numerator']));$d=self::num(self::value($row,(string)$metric['denominator']));if($n!==null&&$d!==null&&$d>0){$groups[$key]['numerator']+=$n;$groups[$key]['denominator']+=$d;}}elseif(($v=self::rowMetric($row,$metric))!==null)$groups[$key]['value']+=$v;$groups[$key]['rows']++;}foreach($groups as &$group){if(($metric['type']??'')==='distinct')$group['value']=(float)count($group['distinct']);if(($metric['type']??'')==='ratio')$group['value']=$group['denominator']>0?($group['numerator']/$group['denominator']*100):0.0;unset($group['distinct'],$group['numerator'],$group['denominator']);}unset($group);return $groups;}
