 public static function analyze(int $workspaceId,int $datasetId,string $question,?int $conversationId=null):array{
  $question=trim($question);if($question===''||strlen($question)>1500)return self::insuff('Pertanyaan kosong atau terlalu panjang.');$db=$GLOBALS['pdo'];$st=$db->prepare('SELECT * FROM datasets WHERE id=? AND workspace_id=? LIMIT 1');$st->execute([$datasetId,$workspaceId]);$dataset=$st->fetch();if(!$dataset)return self::insuff('Dataset tidak ditemukan di workspace ini.');$schema=json_decode((string)$dataset['schema_json'],true)?:[];$st=$db->prepare('SELECT row_json FROM dataset_rows WHERE dataset_id=? ORDER BY `row_number` LIMIT 10000');$st->execute([$datasetId]);$rows=[];while($raw=$st->fetchColumn()){$r=json_decode((string)$raw,true);if(is_array($r))$rows[]=$r;}if(!$rows)return self::insuff('Dataset belum memiliki baris yang dapat dianalisis.');$metric=self::metric($schema,$question);if(!$metric)return self::insuff('Kolom metrik atau definisi pertanyaan tidak dapat dipetakan ke schema dataset.',['dataset'=>$dataset['name'],'rows'=>count($rows),'columns'=>array_column($schema,'name')]);[$filtered,$dateCol,$dateRange]=self::dateFilter($rows,$schema,$question);if(!$filtered)return self::insuff('Tidak ada baris yang cocok dengan periode yang diminta.',['dataset'=>$dataset['name'],'date_range'=>$dateRange,'rows'=>count($rows)]);$q=self::normalized($question);if(preg_match('/(?:kenapa|why|penyebab|causality|cause)/u',$q))return self::insuff('Dataset observasional tidak cukup untuk memastikan penyebab. Tanyakan perbandingan atau pola terukur sebagai gantinya.',['dataset'=>$dataset['name'],'rows'=>count($filtered)]);$ranking=(bool)preg_match('/(?:top\s*\d+|teratas|terbesar|paling|terbanyak|terlaris|highest|largest|most|rank)/u',$q);$trend=(bool)preg_match('/(?:trend|tren|per bulan|per month|perkembangan|growth|pertumbuhan|over time|forecast|prediksi|ramalan|anomali|anomaly)/u',$q);$comparison=(bool)preg_match('/(?:banding|compare|dibanding|vs\.?|versus|year over year|yoy|kenapa|why)/u',$q);$growthProduct=(bool)preg_match('/(?:fastest.{0,40}(?:product|item)|fastest\s+growi