  if($growthProduct){
   $kind='growth';if(!$dateCol||!$dimension)return self::insuff('Peringkat pertumbuhan produk memerlukan kolom produk dan tanggal.',['dataset'=>$dataset['name']]);$byProduct=[];$periodSet=[];$productRows=[];foreach($filtered as $row){$date=self::dateValue(self::value($row,$dateCol));$product=trim((string)self::value($row,$dimension));$value=self::rowMetric($row,$metric);if(!$date||$product===''||$value===null)continue;$period=$date->format('Y-m');$periodSet[$period]=true;$byProduct[$product][$period]=($byProduct[$product][$period]??0)+$value;$productRows[$product]=($productRows[$product]??0)+1;}ksort($periodSet);$periods=array_keys($periodSet);if(count($periods)<6)return self::insuff('Perbandingan pertumbuhan memerlukan sedikitnya enam periode bulanan terisi.',['dataset'=>$dataset['name'],'periods'=>count($periods)]);$window=max(1,min(3,intdiv(count($periods),2)));$firstWindow=array_slice($periods,0,$window);$lastWindow=array_slice($periods,-$window);foreach($byProduct as $product=>$series){$startTotal=0.0;$endTotal=0.0;foreach($firstWindow as $period)$startTotal+=(float)($series[$period]??0);foreach($lastWindow as $period)$endTotal+=(float)($series[$period]??0);$startAverage=$startTotal/$window;$endAverage=$endTotal/$window;if($startAverage<=0)continue;$table[]=['label'=>(string)$product,'value'=>(($endAverage-$startAverage)/abs($startAverage))*100,'rows'=>(int)$productRows[$product]];}if(!$table)return self::insuff('Tidak ada produk dengan baseline positif pada periode awal untuk dibandingkan.',['dataset'=>$dataset['name'],'periods'=>count($periods)]);usort($table,static fn($a,$b)=>$b['value']<=>$a['value']);$table=array_slice($table,0,10);$chart['type']='bar';$chart['labels']=array_column($table,'label');$chart['values']=array_column($table,'value');$metrics[]=['label'=>'Produk dengan pertumbuhan relatif tertinggi','value'=>$table[0]['label'],'kind'=>'text'];$metrics[]=['label'=>'Perubahan relatif','value'=>$table[0]['value'],'kind'=>'percent'];$metrics[]=['label