  }
  elseif(preg_match('/(?:anomali|anomaly)/u',$q)){
   $kind='anomaly';if(!$dateCol)return self::insuff('Deteksi anomali memerlukan kolom tanggal.',['dataset'=>$dataset['name']]);$series=self::timeGroups($filtered,$metric,$dateCol,'month');if(count($series)<6)return self::insuff('Deteksi anomali bulanan memerlukan sedikitnya enam periode terisi.',['dataset'=>$dataset['name'],'periods'=>count($series)]);$vals=array_values($series);$mean=array_sum($vals)/count($vals);$variance=0.0;foreach($vals as $value)$variance+=($value-$mean)**2;$std=sqrt($variance/count($vals));$anomalies=[];foreach($series as $period=>$value){$z=$std>0?($value-$mean)/$std:0.0;if(abs($z)>=2.5)$anomalies[$period]=['value'=>$value,'z_score'=>$z];}$metrics[]=['label'=>'Periode diperiksa','value'=>count($series),'kind'=>'number'];$metrics[]=['label'=>'Periode terindikasi anomali','value'=>count($anomalies),'kind'=>'number'];$metrics[]=['label'=>'Ambang deteksi','value'=>'|z-score| ≥ 2,5','kind'=>'text'];$chart['type']='line';$chart['labels']=array_map([self::class,'nicePeriod'],array_keys($series));$chart['values']=$vals;$source=$anomalies?:array_slice($series,0,10,true);foreach($source as $period=>$value)$table[]=['label'=>self::nicePeriod((string)$period),'value'=>is_array($value)?$value['value']:$value,'z_score'=>is_array($value)?$value['z_score']:null];
